import re
s=open('app/catalog/tasks.py').read()
cur=None; counts={}
for line in s.splitlines():
    m=re.search(r'group_id="(\w+)"',line)
    if m: cur=m.group(1); counts.setdefault(cur,[])
    m2=re.search(r'^\s+Task\(\s*$',line) or re.search(r'Task\("([\w.]+)"',line)
    if m2 and cur is not None:
        nm=re.search(r'Task\(\s*"([\w.]+)"',line)
        counts[cur].append(nm.group(1) if nm else '...')
for k,v in counts.items(): print(f"{k:12} {len(v):3}  {v[:8]}")
print("total", sum(len(v) for v in counts.values()))
EOF
